    y.ticks.forEach(v => { G.add(L.line([[X0, fy(v), 0], [X0 + W, fy(v), 0]], 0x4a5878, { opacity: 0.3 }), lab(y.fmt ? y.fmt(v) : String(v), [X0 - 0.75, fy(v), 0], { size: 17, bg: false })); });
